int pinyin_count() { return 801; }
const char* pinyin_key(int i) { return PINYIN_KEYS[i]; }
const char* pinyin_val(int i) { return PINYIN_VALS[i]; }

/* 二分查找拼音，返回下标或 -1 */
int pinyin_find(const char* s) {
  int lo = 0, hi = 801 - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    int c = strcmp(s, PINYIN_KEYS[mid]);
    if (c == 0) return mid;
    if (c < 0) hi = mid - 1; else lo = mid + 1;
  }
  return -1;
}